/-- The benchmark experiment supplying labeled data and the exact `(X,A)` table.  [the stated conditions](hyp:n,d,eps) [the stated conclusion](goal). -/
def knownMarginalExperiment (n d : Nat) (eps : Real) :
    Set (Measure (Fin n → Obs d) × AuxTable d) :=
  {q | 1 ≤ n ∧ 2 ≤ d ∧ ∃ P : DiscreteLaw d,
    ModelClass d eps P ∧ LabeledIid P n q.1 ∧ q.2 = auxTableOf P}

/-- The inverse-propensity score, written directly in terms of the supplied table.  [the stated conditions](hyp:table,z) [the stated conclusion](goal). -/
noncomputable def knownMarginalScore {d : Nat} (table : AuxTable d) (z : Obs d) : Real :=
  let p := table (z.1, false) + table (z.1, true)
  if z.2.2 then
    if z.2.1 then p / table (z.1, true) else -(p / table (z.1, false))
  else 0

/-- [the stated conditions](hyp:hk,i) defines [the specified object](goal). -/

def parametricRareCell {d k : Nat} (hk : k ≤ d - 1) (i : Fin k) : Fin d :=
  ⟨i.1 + 1, by omega⟩

